import re

html = open("frontend/index.html", encoding="utf-8").read()
js = open("frontend/js/app.js", encoding="utf-8").read()

# Dynamic IDs generated by JS during render
dynamic_ids = {
    "choice-yes", "choice-no", "stepper-save-btn", "stepper-skip-btn",
    "stepper-enum-select", "stepper-num-input", "stepper-text-input",
    "btn-browse-anyway", "btn-show-more",
    "btn-empty-clear-filters", "btn-toggle-more-cats",
    "btn-browse-eligible-saved", "btn-clear-dash-filter"
}

# IDs queried in JS
queried_ids = set(re.findall(r'getElementById\(["\']([\w-]+)["\']\)', js))
static_queried = queried_ids - dynamic_ids

# IDs defined in HTML
html_ids = set(re.findall(r'id=["\']([\w-]+)["\']', html))

missing = static_queried - html_ids
print("Queried IDs:", len(queried_ids))
print("Static queried IDs:", len(static_queried))
print("HTML IDs found:", len(html_ids))

if missing:
    print("ERROR - Missing IDs in HTML:", missing)
else:
    print("SUCCESS: All static JS hooks are present in HTML!")

assert len(missing) == 0
